89	// Program represents a semantically-analyzed Pulumi HCL2 program.
90	type Program struct {
91		Nodes []Node
92	
93		files []*syntax.File
94	
95		binder *binder
96	}
97	
98	// NewDiagnosticWriter creates a new hcl.DiagnosticWriter for use with diagnostics generated by the program.
99	func (p *Program) NewDiagnosticWriter(w io.Writer, width uint, color bool) hcl.DiagnosticWriter {
100		return syntax.NewDiagnosticWriter(w, p.files, width, color)
101	}
102	
103	// BindExpression binds an HCL2 expression in the top-level context of the program.
104	func (p *Program) BindExpression(node hclsyntax.Node) (model.Expression, hcl.Diagnostics) {
105		return p.binder.bindExpression(node)
106	}
107	
108	// Packages returns the list of package referenced used by this program.
109	func (p *Program) Packages() []*schema.Package {
110		refs := p.PackageReferences()
111		defs := make([]*schema.Package, len(refs))
112		for i, ref := range refs {
113			def, err := ref.Definition()
114			if err != nil {
115				panic(fmt.Errorf("loading package definition: %w", err))
116			}
117			defs[i] = def
118		}
119		return defs
120	}
121	
122	// PackageReferences returns the list of package referenced used by this program.
123	func (p *Program) PackageReferences() []schema.PackageReference {
124		components := p.CollectComponents()
125	
126		keys := map[string]struct{}{}
127		for k := range p.binder.referencedPackages {
128			keys[k] = struct{}{}
129		}
130	
131		for _, component := range components {
132			pkgs := component.Program.binder.referencedPackages
133			for k := range pkgs {
134				keys[k] = struct{}{}
135			}
136		}
137	
138		sortedKeys := slice.Prealloc[string](len(keys))
139		for k := range keys {
140			sortedKeys = append(sortedKeys, k)
141		}
142		sort.Strings(sortedKeys)
143	
144		values := slice.Prealloc[schema.PackageReference](len(p.binder.referencedPackages))
145		for _, k := range sortedKeys {
146			if pkg, ok := p.binder.referencedPackages[k]; ok {
147				values = append(values, pkg)
148				continue
149			}
150			for _, component := range components {
151				if pkg, ok := component.Program.binder.referencedPackages[k]; ok {
152					values = append(values, pkg)
153					break
154				}
155			}
156		}
157	
158		return values
159	}
160	
161	// PackageSnapshots returns the list of packages schemas used by this program. If a referenced package is partial,
162	// its returned value is a snapshot that contains only the package members referenced by the program. Otherwise, its
163	// returned value is the full package definition.
164	func (p *Program) PackageSnapshots() ([]*schema.Package, error) {
165		keys := slice.Prealloc[string](len(p.binder.referencedPackages))
166		for k := range p.binder.referencedPackages {
167			keys = append(keys, k)
168		}
169		sort.Strings(keys)
170	
171		values := slice.Prealloc[*schema.Package](len(p.binder.referencedPackages))
172		for _, k := range keys {
173			ref := p.binder.referencedPackages[k]
174	
175			var pkg *schema.Package
176			var err error
177			if partial, ok := ref.(*schema.PartialPackage); ok {
178				pkg, err = partial.Snapshot()
179			} else {
180				pkg, err = ref.Definition()
181			}
182			if err != nil {
183				return nil, fmt.Errorf("defining package '%v': %w", ref.Name(), err)
184			}
185	
186			values = append(values, pkg)
187		}
188		return values, nil
189	}
190	
191	func (p *Program) Source() map[string]string {
192		source := make(map[string]string)
193		for _, file := range p.files {
194			source[file.Name] = string(file.Bytes)
195		}
196		return source
197	}
198	
199	// writeSourceFiles writes the source files of the program, including those files of used components into the
200	// provided file system starting from a root directory.
201	func (p *Program) writeSourceFiles(directory string, fs afero.Fs, seenPaths map[string]bool) error {
202		// create the directory if it doesn't already exist
203		err := fs.MkdirAll(directory, 0o755)
204		if err != nil {
205			return fmt.Errorf("could not create output directory: %w", err)
206		}
207	
208		for _, file := range p.files {
209			outputFile := path.Join(directory, file.Name)
210			err := afero.WriteFile(fs, outputFile, file.Bytes, 0o600)
211			if err != nil {
212				return fmt.Errorf("could not write output program: %w", err)
213			}
214		}
215	
216		for _, node := range p.Nodes {
217			switch node := node.(type) {
218			case *Component:
219				componentDirectory := path.Join(directory, node.source)
220				if _, seen := seenPaths[componentDirectory]; !seen {
221					seenPaths[componentDirectory] = true
222					err = node.Program.writeSourceFiles(componentDirectory, fs, seenPaths)
223					if err != nil {
224						return err
225					}
226				}
227			}
228		}
229	
230		return nil
231	}
232	
233	// WriteSource writes the source files of the program, including those files of used components into the
234	// provided file system.
235	func (p *Program) WriteSource(fs afero.Fs) error {
236		seenPaths := map[string]bool{}
237		return p.writeSourceFiles("/", fs, seenPaths)
238	}
239	
240	// collectComponentsRecursive is a helper function to find all used components in a program
241	// and recursively searches of nested components from sub programs.
242	func (p *Program) collectComponentsRecursive(components map[string]*Component) {
243		for _, node := range p.Nodes {
244			switch node := node.(type) {
245			case *Component:
246				if _, seen := components[node.DirPath()]; !seen {
247					components[node.DirPath()] = node
248					node.Program.collectComponentsRecursive(components)
249				}
250			}
251		}
252	}
