25	func errorf(subject hcl.Range, f string, args ...any) *hcl.Diagnostic {
26		return diagf(hcl.DiagError, subject, f, args...)
27	}
28	
29	func diagf(severity hcl.DiagnosticSeverity, subject hcl.Range, f string, args ...any) *hcl.Diagnostic {
30		message := fmt.Sprintf(f, args...)
31		return &hcl.Diagnostic{
32			Severity: severity,
33			Summary:  message,
34			Detail:   message,
35			Subject:  &subject,
36		}
37	}
38	
39	func labelsErrorf(block *hclsyntax.Block, f string, args ...any) *hcl.Diagnostic {
40		startRange := block.LabelRanges[0]
41	
42		diagRange := hcl.Range{
43			Filename: startRange.Filename,
44			Start:    startRange.Start,
45			End:      block.LabelRanges[len(block.LabelRanges)-1].End,
46		}
47		return errorf(diagRange, f, args...)
48	}
49	
50	func malformedToken(token string, sourceRange hcl.Range) *hcl.Diagnostic {
51		return errorf(sourceRange, "malformed token '%v': expected 'pkg:module:member' or 'pkg:member'", token)
52	}
53	
54	func unknownPackage(pkg string, tokenRange hcl.Range) *hcl.Diagnostic {
