50	func annotateAttributeValue(expr model.Expression, attributeType schema.Type) model.Expression {
51		if optionalType, ok := attributeType.(*schema.OptionalType); ok {
52			return annotateAttributeValue(expr, optionalType.ElementType)
53		}
54	
55		switch attrValue := expr.(type) {
56		case *model.ObjectConsExpression:
57			if schemaObjectType, ok := attributeType.(*schema.ObjectType); ok {
58				schemaProperties := make(map[string]schema.Type)
59				for _, schemaProperty := range schemaObjectType.Properties {
60					schemaProperties[schemaProperty.Name] = schemaProperty.Type
61				}
62	
63				for _, item := range attrValue.Items {
64					// annotate the nested object properties
65					// here when the key is a literal such as { key = <inner value> }
66					keyLiteral, isLit := item.Key.(*model.LiteralValueExpression)
67					if isLit {
68						correspondingSchemaType, ok := schemaProperties[keyLiteral.Value.AsString()]
69						if ok {
70							item.Value = annotateAttributeValue(item.Value, correspondingSchemaType)
71						}
72					}
73	
74					// here when the key is a quoted literal such as { "key" = <inner value> }
75					if templateExpression, ok := item.Key.(*model.TemplateExpression); ok && len(templateExpression.Parts) == 1 {
76						if literalValue, ok := templateExpression.Parts[0].(*model.LiteralValueExpression); ok {
77							if correspondingSchemaType, ok := schemaProperties[literalValue.Value.AsString()]; ok {
78								item.Value = annotateAttributeValue(item.Value, correspondingSchemaType)
79							}
80						}
81					}
82				}
83				return attrValue.WithType(func(attrValueType model.Type) *model.ObjectConsExpression {
84					annotateObjectProperties(attrValueType, attributeType)
85					return attrValue
86				})
87			}
88	
89			return attrValue
90	
91		case *model.TupleConsExpression:
92			if schemaArrayType, ok := attributeType.(*schema.ArrayType); ok {
93				elementType := schemaArrayType.ElementType
94				for _, arrayExpr := range attrValue.Expressions {
95					annotateAttributeValue(arrayExpr, elementType)
96				}
97			}
98	
99			return attrValue
100		case *model.FunctionCallExpression:
101			if attrValue.Name == IntrinsicConvert {
102				converterArg := attrValue.Args[0]
103				annotateAttributeValue(converterArg, attributeType)
104			}
105	
106			return attrValue
107		default:
108			return expr
109		}
110	}
