156							discriminatorValue = literalValue.Value.AsString()
157							break
158						}
159					}
160				}
161			}
162		}
163	
164		if discriminatorValue == "" {
165			return union
166		}
167	
168		if correspondingTypeToken, ok := union.Mapping[discriminatorValue]; ok {
169			for _, schemaType := range union.ElementTypes {
170				if schemaObjectType, ok := codegen.UnwrapType(schemaType).(*schema.ObjectType); ok {
