func diagSummaries(diags hcl.Diagnostics) []string {
	var out []string
	for _, d := range diags {
		out = append(out, d.Summary)
	}
	return out
}

func TestScratchHookBasic(t *testing.T) {
	t.Parallel()
	src := `
hook myHook {
  command = ["echo", args.urn, args.id, args.name, args.type]
  onDryRun = true
}
`
	program, diags, err := ParseAndBindProgram(t, src, "hook.pp")
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	if diags.HasErrors() {
		t.Fatalf("unexpected diags: %v", diags)
	}
	hooks := program.Hooks()
	if len(hooks) != 1 {
		t.Fatalf("expected 1 hook, got %d", len(hooks))
	}
	if hooks[0].Name() != "myHook" {
		t.Fatalf("wrong name %q", hooks[0].Name())
	}
	// args map fields
	src2 := `
hook h2 {
  command = [args.new_inputs["a"], args.old_inputs["b"], args.new_outputs["c"], args.old_outputs["d"]]
}
`
	_, diags2, err := ParseAndBindProgram(t, src2, "hook.pp")
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	if diags2.HasErrors() {
		t.Fatalf("unexpected diags for map fields: %v", diags2)
	}
}

