func TestScratchResourceHooks(t *testing.T) {
	t.Parallel()
	src := `
hook foo {
  command = ["echo"]
}

resource res "random:index/randomPet:RandomPet" {
  options {
    hooks = { beforeCreate = [foo] }
  }
}
`
	program, diags, err := ParseAndBindProgram(t, src, "hook.pp")
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	if diags.HasErrors() {
		t.Fatalf("unexpected diags: %v", diags)
	}
	var res *pcl.Resource
	for _, n := range program.Nodes {
		if r, ok := n.(*pcl.Resource); ok {
			res = r
		}
	}
	if res == nil || res.Options == nil || res.Options.Hooks == nil {
		t.Fatalf("resource hooks not set")
	}
	v, evalDiags := res.Options.Hooks.Evaluate(&hcl.EvalContext{})
	if evalDiags.HasErrors() {
		t.Fatalf("eval diags: %v", evalDiags)
	}
	want := cty.ObjectVal(map[string]cty.Value{
		"beforeCreate": cty.TupleVal([]cty.Value{cty.StringVal("foo")}),
	})
	if !v.RawEquals(want) {
		t.Fatalf("hooks eval mismatch:\nwant: %#v\ngot:  %#v", want, v)
	}
}

